Given an integer array arr[], which denotes the positions of stalls. All the positions are distinct. There are k aggressive cows.Assign the cows to the stalls such that the minimum distance between any two cows is maximized.Examples: Input: arr[] = [1, 2, 4, 8, 9], k = 3Output: 3Explanation: The first cow can be placed at arr[0], the second at arr[2], and the third at arr[3]. The minimum distance between any two cows is 3 (between arr[0] and arr[2]), which is the maximum possible among all valid arrangementsInput: arr[] = [10, 1, 2, 7, 5], k = 3Output: 4Explanation: The first cow can be placed at arr[0], the second at arr[1], and the third at arr[4]. In this arrangement, the minimum distance between any two cows is 4 (between arr[1] and arr[4]), which is the maximum possible among all valid arrangements.Try It YourselfTable of Content[Naive Approach] By iterating over all possible distances[Expected Approach] Using Binary Search on Answer[Naive Approach] By iterating over all possible distancesThe idea is to place k cows such that the minimum distance between any two is maximized. We sort the array and try all possible distances from 1 to the maximum gap between stalls.For each distance, we check if cows can be placed by assigning the first cow to the first stall, and placing the next cow only if the gap from the last placed cow is at least that distance.If placement is possible, we update our answer; the largest such distance is returned.
            C++

    #include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

bool check(vector<int> &arr, int k, int dist) {

    // Place first cow at 0th index
    int cnt = 1;
    int prev = arr[0];

    for (int i = 1; i < arr.size(); i++) {

        // If the current stall is at least dist away
        // from the previous one place the cow here
        if (arr[i] - prev >= dist) {
            prev = arr[i];
            cnt++;
        }
    }

    // Return true if we are able to place all 'k' cows
    return (cnt >= k);
}

int aggressiveCows(vector<int> &arr, int k) {

    // sorting the array to ensure stalls in sequence
    sort(arr.begin(), arr.end());
    int res = 0;

    // Minimum and maximum possible minimum distance
    // between two stalls
    int minDist = 1;
    int maxDist = arr.back() - arr[0];

    // Iterating through all possible distances
    for (int i = minDist; i <= maxDist; i++) {

        // If we can place k cows with the
        // current distance i, update the res
        if (check(arr, k, i))
            res = i;
    }

    return res;
}

int main() {
    vector<int> arr = {1, 2, 4, 8, 9};
    int k = 3;

    int ans = aggressiveCows(arr, k);
    cout << ans;

    return 0;
}


